function interpolate(text, params) {
  return String(text).replace(/\{\{(.*?)\}\}/g, (_, key) => String(params[key.trim()] ?? ''))
}

function lookup(lang, keyPath, defaultValue, params = {}) {
  try {
    const keyText = String(keyPath ?? '')
    const parts = keyText.split('.')
    const locales = [TRANSLATIONS[lang], TRANSLATIONS.en].filter(Boolean)

    for (const locale of locales) {
      let node = locale
      let found = true
      for (const p of parts) {
        node = node?.[p]
        if (node == null) {
          found = false
          break
        }
      }
      if (found) {
        if (typeof node === 'string') {
          return interpolate(node, params)
        }
        return node
      }

      const phraseMatch = locale?.phrases?.[keyText]
      if (typeof phraseMatch === 'string') {
        return interpolate(phraseMatch, params)
      }
    }

    if (typeof defaultValue === 'string') {
      return interpolate(defaultValue, params)
    }
    return defaultValue
  } catch {
    return defaultValue
  }
}

export function TranslationProvider({ languageCode = 'en', children }) {
  const value = useMemo(() => ({ languageCode, t: (key, def, params) => lookup(languageCode || 'en', key, def, params) }), [languageCode])
  return React.createElement(TranslationContext.Provider, { value }, children)
}

export function useTranslation() {
  return useContext(TranslationContext)
}

export default {
  TRANSLATIONS,
}
